    // ---- 9. SubscribeMatch ----
    #[tokio::test]
    async fn subscribe_match_happy_returns_receiver() {
        let (_s, v2) = svc_v2();
        let host = make_player("host");
        let r = v2
            .create_match(
                conv::player_from_proto(&host),
                GameModeV2::Room,
                Some("R".to_string()),
                None,
                4,
                2,
                0,
            )
            .await
            .unwrap();
        let rx = v2
            .subscribe_match(r.match_id, &conv::player_from_proto(&host), false)
            .await
            .unwrap();
        // 接收方存在即可 (后续测试可 publish 后验证)
        drop(rx);
    }

